".subnav{display:flex;flex-wrap:wrap;gap:8px;margin:32px 0 24px!important;background:#0d2237;border:1px solid #2b4d67;border-radius:15px;padding:10px}\n"
".subnav a{display:inline-flex;align-items:center;justify-content:center;gap:5px;padding:10px 13px;border:1px solid transparent;border-radius:10px;color:#b5d5ee;text-decoration:none;font-size:13px;font-weight:650}\n"
".subnav a:hover,.subnav a:focus-visible,.subnav a.active{background:#214466;color:#fff;border-color:#416b8e}\n"
"@media(max-width:600px){header .toolbar{gap:23px!important}header .lf-wordmark{font-size:16px}header .toolbar-links{width:100%!important}header .toolbar-links a{flex:1;min-width:0;padding:12px 10px!important}.subnav{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}.subnav a{font-size:12px;padding:11px 3px;text-align:center}}\n"
"</style></head>\n"
"<body><main>\n"
"<header><div class=\"toolbar\"><div class=\"lf-wordmark\"><span class=\"lf-mark\" aria-hidden=\"true\"><svg viewBox=\"0 0 64 64\" width=\"38\" height=\"38\" xmlns=\"http://www.w3.org/2000/svg\"><defs><linearGradient id=\"lfbolt\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop stop-color=\"#fff4a2\"/><stop offset=\".35\" stop-color=\"#ffd32b\"/><stop offset=\"1\" stop-color=\"#ffad16\"/></linearGradient></defs><rect width=\"64\" height=\"64\" rx=\"16\" fill=\"#0a2859\"/><path d=\"M12 21 Q12 14 20 14 Q24 5 32 8 Q40 7 43 15 Q53 15 53 23 Q53 30 44 30 L21 30 Q12 30 12 21\" fill=\"#fff\" stroke=\"#05182d\" stroke-width=\"3.5\" stroke-linejoin=\"round\"/><path d=\"M30 29 L21 43 L32 40 L29 57 L48 34 L37 36 L41 27\" fill=\"url(#lfbolt)\" stroke=\"#06203a\" stroke-width=\"3\" stroke-linejoin=\"round\"/><path d=\"M47 43 v13 a5 3 0 1 1 -3 -4 V43 l12 -3 v11 a5 3 0 1 1 -3 -4 V39 Z\" fill=\"#9fd9ff\"/></svg></span><span>LYRIC<span class=\"accent\">FLASH</span><small>DEVICE STUDIO</small></span></div><div class=\"toolbar-links\"><a class=\"settings-link active\" href=\"/\">Settings</a><a class=\"firmware-link\" href=\"/firmware\">Firmware</a></div></div></header><nav class=\"subnav\" aria-label=\"Settings menu\"><a href=\"/#network\">◉ Wi-Fi</a><a href=\"/settings\" class=\"active\" aria-current=\"page\">◷ Clocks</a><a href=\"/settings#weather-settings\">☁ Weather</a><a href=\"/#lyrics\">♫ Lyrics</a><a href=\"/#device\">⚙ Device</a><a href=\"/#status-section\">◇ Status</a></nav>\n"
"<h1>Clock Studio</h1><p>Choose a face, see it immediately, and adjust that face's own settings. Changes stay in preview until you save to LyricFlash.</p>\n"
"<div class=\"layout\">\n"
"<div class=\"panel preview-area\">\n"
"<h2 id=\"face-title\">Clock Preview</h2>\n"
"<div class=\"preview-circle\"><svg id=\"clock-preview\" viewBox=\"0 0 466 466\" role=\"img\" aria-label=\"Live preview of selected clock face\"></svg></div>\n"
"<p class=\"hint\">Interactive browser preview · device time and fonts may differ slightly</p>\n"
"<label>Clock face<select id=\"clock_face\"><option value=\"0\">Rolex Diver</option><option value=\"1\">Midnight Digital</option><option value=\"2\">Classic Analog</option><option value=\"3\">Retro Green LCD</option><option value=\"4\">Sundial</option><option value=\"5\">Basic Custom</option></select></label>\n"
"</div>\n"
"<div>\n"
"<section class=\"panel\">\n"
"<h2>Customize selected face</h2><p class=\"small\">Each of the six faces keeps its own colours and display options. Select a different face to edit it independently.</p>\n"
"<div class=\"grid\">\n"
"<label>Dial / background<input id=\"face_background\" type=\"color\"></label>\n"
"<label>Hands / text<input id=\"face_foreground\" type=\"color\"></label>\n"
"<label>Accent / markers<input id=\"face_accent\" type=\"color\"></label>\n"
"</div>\n"
"<div class=\"grid\">\n"
"<label><input id=\"face_show_date\" type=\"checkbox\">Show date</label>\n"
"<label><input id=\"face_show_seconds\" type=\"checkbox\">Show second hand / seconds</label>\n"
"<label><input id=\"face_show_battery\" type=\"checkbox\">Show battery</label>\n"
"<label><input id=\"face_24h\" type=\"checkbox\">24-hour clock</label>\n"
"</div>\n"
"<div class=\"actions\"><button class=\"secondary\" id=\"reset-face\" type=\"button\">Reset this face</button></div>\n"
"</section>\n"
"<section class=\"panel\" id=\"basic-options\">\n"
"<h2>Basic Custom controls</h2><div class=\"grid\">\n"
"<label>Font preset<select id=\"font_style\"><option value=\"0\">Balanced</option><option value=\"1\">Large / narrow</option><option value=\"2\">Compact</option><option value=\"3\">Spaced</option><option value=\"4\">Fine / compact</option></select></label>\n"
"<label>Time size (%)<input id=\"font_size\" type=\"number\" min=\"0\" max=\"100\" step=\"1\"></label>\n"
"<label>Ring style<select id=\"ring_mode\"><option value=\"0\">Solid</option><option value=\"1\">Two-colour</option><option value=\"2\">Three-colour</option></select></label>\n"
"<label><input id=\"show_date\" type=\"checkbox\">Date in Basic</label>\n"
"<label><input id=\"weather\" type=\"checkbox\">Weather in Basic</label>\n"
"</div><div class=\"grid\">\n"
"<label>Background<input id=\"background\" type=\"color\"></label>\n"
"<label>Time text<input id=\"foreground\" type=\"color\"></label>\n"
"<label>Ring colour 1<input id=\"ring_a\" type=\"color\"></label>\n"
"<label id=\"ring-b-row\">Ring colour 2<input id=\"ring_b\" type=\"color\"></label>\n"
"<label id=\"ring-c-row\">Ring colour 3<input id=\"ring_c\" type=\"color\"></label>\n"
"</div>\n"
"</section>\n"
"<section class=\"panel\"><h2>Weather</h2>\n"
"<label><input id=\"weather_enabled\" type=\"checkbox\">Enable weather updates</label>\n"
"<div class=\"grid\">\n"
"<label>City / place<input id=\"city\" type=\"text\" maxlength=\"47\" placeholder=\"e.g. Big White\"></label>\n"
"<label>Refresh schedule<select id=\"interval_minutes\"><option value=\"15\">15 minutes</option><option value=\"30\">30 minutes</option><option value=\"60\">60 minutes</option><option value=\"120\">120 minutes</option></select></label>\n"
"</div><p class=\"small\">A changed weather location or schedule refreshes promptly after saving, then uses this interval.</p>\n"
"</section>\n"
"<section class=\"panel\"><h2>Save to device</h2>\n"
"<p class=\"small\">No PIN, authorization prompt, or firmware update is required to change clock settings.</p>\n"
"<div class=\"actions\"><button id=\"save\" type=\"button\">Save clock settings</button><button class=\"secondary\" id=\"refresh\" type=\"button\">Diagnostics</button></div>\n"
"<div id=\"status\" role=\"status\">Reading settings…</div>\n"
"<pre id=\"diagnostics\" hidden>Loading diagnostics…</pre>\n"
"</section>\n"
"</div></div>\n"
"</main><script>\n"
"const fields=['clock_face','weather_enabled','font_style','font_size','ring_mode','show_date','weather','background','foreground','ring_a','ring_b','ring_c','city','interval_minutes'];\n"
"const names=['Rolex Diver','Midnight Digital','Classic Analog','Retro Green LCD','Sundial','Basic Custom'];\n"
"const defaults=[\n"
" {background:0x070f14,foreground:0xd8ece9,accent:0x40c0e6},\n"
" {background:0x030815,foreground:0xedf7ff,accent:0x7dceff},\n"
" {background:0x080c13,foreground:0xe5edf8,accent:0x6dbfff},\n"
" {background:0xa7c7a0,foreground:0x162c1f,accent:0x364641},\n"
" {background:0xc8bb94,foreground:0x332719,accent:0xa88e55},\n"
" {background:0x030810,foreground:0xf0f8ff,accent:0x268bff}\n"
"].map(p=>({...p,show_date:true,show_seconds:true,show_battery:true,time_24h:false}));\n"
"let faceProfiles=defaults.map(p=>({...p}));let activeFace=0;\n"
"const $=s=>document.getElementById(s),status=t=>$('status').textContent=t;\n"
"const hex=n=>'#'+Number(n).toString(16).padStart(6,'0');\n"
"const nval=id=>Number($(id).value);\n"
"function readProfile(){let p=faceProfiles[activeFace];for(let name of ['background','foreground','accent'])p[name]=parseInt($('face_'+name).value.slice(1),16);\n"
" for(let name of ['show_date','show_seconds','show_battery','24h'])p[name==='24h'?'time_24h':name]=$('face_'+name).checked;\n"
" if(activeFace===5){$('background').value=hex(p.background);$('foreground').value=hex(p.foreground);$('show_date').checked=p.show_date;}}\n"
"function writeProfile(){let p=faceProfiles[activeFace];for(let name of ['background','foreground','accent'])$('face_'+name).value=hex(p[name]);\n"
" for(let name of ['show_date','show_seconds','show_battery','24h'])$('face_'+name).checked=!!p[name==='24h'?'time_24h':name];\n"
" $('basic-options').hidden=activeFace!==5;\n"
" if(activeFace===5){$('background').value=hex(p.background);$('foreground').value=hex(p.foreground);$('show_date').checked=p.show_date;}\n"
" $('face-title').textContent=names[activeFace];updateRingOptions();render();}\n"
"function updateRingOptions(){const mode=nval('ring_mode');$('ring-b-row').hidden=mode===0;$('ring-c-row').hidden=mode!==2;}\n"
"function tickMarks(c,r=185){let lines='';for(let i=0;i<60;i++){let a=(i*6-90)*Math.PI/180,m=i%5===0,inner=m?r-18:r-5;lines+='<line x1=\"'+(233+Math.cos(a)*inner)+'\" y1=\"'+(233+Math.sin(a)*inner)+'\" x2=\"'+(233+Math.cos(a)*r)+'\" y2=\"'+(233+Math.sin(a)*r)+'\" stroke=\"'+c+'\" stroke-width=\"'+(m?5:2)+'\"/>'}return lines;}\n"
"function analogHands(f,minutes,seconds){let hour=(new Date().getHours()%12)*30+minutes*.5,min=minutes*6,sec=seconds*6;\n"
" let hand=(a,len,w,col)=>{let theta=(a-90)*Math.PI/180;return '<line x1=\"233\" y1=\"233\" x2=\"'+(233+Math.cos(theta)*len)+'\" y2=\"'+(233+Math.sin(theta)*len)+'\" stroke=\"'+col+'\" stroke-linecap=\"round\" stroke-width=\"'+w+'\"/>'};\n"
" return hand(hour,94,11,f.foreground)+hand(min,133,7,f.foreground)+(f.show_seconds?hand(sec,164,3,f.accent):'')+'<circle cx=\"233\" cy=\"233\" r=\"10\" fill=\"'+f.foreground+'\"/>';}\n"
"function render(){const profile=faceProfiles[activeFace],f={...profile,background:hex(profile.background),foreground:hex(profile.foreground),accent:hex(profile.accent)},now=new Date(),time=f.time_24h?now.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):now.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}),date=now.toLocaleDateString('en-US',{month:'short',day:'numeric'}),min=now.getMinutes()+now.getSeconds()/60,sec=now.getSeconds(),text=(y,size,t,col=f.foreground,tracking=0)=>'<text x=\"233\" y=\"'+y+'\" text-anchor=\"middle\" fill=\"'+col+'\" font-family=\"Montserrat,Arial,system-ui\" font-size=\"'+size+'\" letter-spacing=\"'+tracking+'\" font-weight=\"650\">'+t+'</text>';\n"
"let svg='<circle cx=\"233\" cy=\"233\" r=\"231\" fill=\"'+f.background+'\" stroke=\"'+f.accent+'\" stroke-width=\"8\"/>';\n"
"if([0,2].includes(activeFace)){svg+='<circle cx=\"233\" cy=\"233\" r=\"209\" fill=\"none\" stroke=\"'+f.accent+'\" stroke-width=\"3\"/>'+tickMarks(f.accent);\n"
"svg+=analogHands(f,min,sec);if(activeFace===0&&f.show_date)svg+='<rect x=\"315\" y=\"220\" width=\"46\" height=\"32\" rx=\"4\" fill=\"#edf6f4\"/><text x=\"338\" y=\"242\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"bold\" fill=\"#132b36\">'+now.getDate()+'</text>';\n"
"else if(f.show_date)svg+=text(337,18,date,f.accent);\n"
"}\n"
"else if(activeFace===1){svg+='<circle cx=\"233\" cy=\"233\" r=\"200\" stroke=\"'+f.accent+'\" stroke-width=\"3\" fill=\"none\"/>';\n"
"svg+=text(244,65,time)+(f.show_date?text(311,23,date,f.accent):'');}\n"
"else if(activeFace===3){svg+='<rect x=\"54\" y=\"126\" width=\"358\" height=\"220\" rx=\"18\" fill=\"'+f.background+'\" stroke=\"'+f.accent+'\" stroke-width=\"10\"/>';\n"
"svg+=text(256,63,time)+(f.show_date?text(196,22,date):'')+text(301,15,'RETRO LCD',f.accent);}\n"
"else if(activeFace===4){svg+='<circle cx=\"233\" cy=\"233\" r=\"176\" fill=\"none\" stroke=\"'+f.accent+'\" stroke-width=\"3\"/>'+tickMarks(f.accent,170);\n"
"svg+=analogHands(f,min,sec)+(f.show_date?text(371,20,date):'');}\n"
"else{const a=$('ring_a').value,b=$('ring_b').value,c=$('ring_c').value,mode=nval('ring_mode'),fs=Math.min(100,Math.max(0,nval('font_size'))),style=nval('font_style');\n"
"const tracking=[0,3,1,6,2][style]||0;\n"
"const px=style===1?(fs>70?48:40):style===2?(fs>70?40:32):style===3?(fs>70?48:36):style===4?(fs>70?40:28):fs>80?48:fs>45?40:32;\n"
"const stops=mode===2?[[0,a],[.333,b],[.667,c],[1,a]]:mode===1?[[0,a],[.5,b],[1,a]]:[[0,a],[1,a]];\n"
"svg+='<defs><linearGradient id=\"basic-gradient\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">'+stops.map(s=>'<stop offset=\"'+s[0]+'\" stop-color=\"'+s[1]+'\"/>').join('')+'</linearGradient></defs><circle cx=\"233\" cy=\"233\" r=\"191\" stroke=\"'+(mode===0?a:'url(#basic-gradient)')+'\" stroke-width=\"12\" fill=\"none\"/>';\n"
"svg+=text(249,px,time,f.foreground,tracking)+(f.show_date?text(311,23,date):'')+($('weather').checked?text(368,18,'Weather',f.accent):'');}\n"
"if(f.show_battery)svg+='<g fill=\"'+f.accent+'\"><rect x=\"193\" y=\"66\" width=\"73\" height=\"25\" rx=\"6\" fill=\"none\" stroke=\"'+f.accent+'\" stroke-width=\"3\"/><rect x=\"266\" y=\"73\" width=\"6\" height=\"11\" rx=\"2\"/><rect x=\"200\" y=\"72\" width=\"43\" height=\"13\" rx=\"2\"/></g>';\n"
"$('clock-preview').innerHTML=svg;\n"
"}\n"
"async function request(url,opt){const r=await fetch(url,{cache:'no-store',...opt}),t=await r.text();if(!r.ok)throw Error('HTTP '+r.status+': '+t);return JSON.parse(t);}\n"
"async function load(){try{const d=await request('/api/basic');for(let id of fields){let el=$(id),v=d[id];if(v===undefined)continue;if(el.type==='checkbox')el.checked=!!v;else if(el.type==='color')el.value=hex(v);else el.value=v;}\n"
" if(Array.isArray(d.face_profiles)&&d.face_profiles.length===6)faceProfiles=d.face_profiles.map((p,i)=>({...defaults[i],...p}));\n"
" activeFace=nval('clock_face');writeProfile();status('Settings loaded — customize and save when ready.');}\n"
" catch(e){status('Could not load saved settings: '+e.message);writeProfile();}}\n"
"async function save(){readProfile();const data={};for(let name of fields){const el=$(name);data[name]=el.type==='checkbox'?el.checked:el.type==='color'?parseInt(el.value.slice(1),16):el.type==='number'||el.tagName==='SELECT'?Number(el.value):el.value;}\n"
"data.face_profiles=faceProfiles;$('save').disabled=true;status('Saving settings…');\n"
"try{await request('/api/basic',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});status('Saved. Your clock settings are stored on LyricFlash.');}catch(e){status('Save failed: '+e.message)}finally{$('save').disabled=false}}\n"
"async function diagnostics(){let p=$('diagnostics');p.hidden=!p.hidden;if(p.hidden)return;try{p.textContent=JSON.stringify(await request('/api/diagnostics'),null,2);}catch(e){p.textContent=e.message;}}\n"
"$('clock_face').addEventListener('change',()=>{readProfile();activeFace=nval('clock_face');writeProfile();});\n"
"for(let id of ['face_background','face_foreground','face_accent','face_show_date','face_show_seconds','face_show_battery','face_24h'])$(id).addEventListener('input',()=>{readProfile();render();});\n"
"for(let id of ['font_style','font_size','ring_mode','show_date','weather','ring_a','ring_b','ring_c'])$(id).addEventListener('input',()=>{if(id==='show_date'&&activeFace===5){faceProfiles[5].show_date=$('show_date').checked;$('face_show_date').checked=$('show_date').checked;}if(id==='ring_mode')updateRingOptions();render();});\n"
"for(let id of ['background','foreground'])$(id).addEventListener('input',()=>{if(activeFace===5){faceProfiles[5][id]=parseInt($(id).value.slice(1),16);$('face_'+id).value=$(id).value;}render();});\n"
"$('reset-face').onclick=()=>{faceProfiles[activeFace]={...defaults[activeFace]};writeProfile();status(names[activeFace]+' restored to defaults in preview. Save to apply.');};\n"
"$('ring_mode').addEventListener('change',()=>{updateRingOptions();render();});\n"
"$('save').onclick=save;$('refresh').onclick=diagnostics;\n"
"load();setInterval(render,1000);\n"
"</script></body></html>\n"
;
